from pathlib import Path
import argparse, os
parser = argparse.ArgumentParser(description="Build Charlot Crea static site")
parser.add_argument('--production', action='store_true', help='Enable indexing and production URLs')
parser.add_argument('--site-url', help='Override the public origin, e.g. https://www.charlotcrea.com')
args = parser.parse_args()
os.environ['SITE_ENV'] = 'production' if args.production else 'preview'
if args.site_url:
 os.environ['SITE_URL'] = args.site_url
import json
D=Path('dist')
# All page HTML is generated; clear previous language outputs before rebuilding.
import shutil
for language in ('en', 'tr'):
 shutil.rmtree(D/language, ignore_errors=True)
