def cards(ps):
 return ''.join(f'<a class="project-card" href="/en/projects/project-{i}/" data-country="{country}"><div class="picture"><img src="/assets/project-{i}.jpg" loading="lazy" alt="{name} — selected photography from the Charlot Crea portfolio"></div><div class="project-info"><div><h3>{name}</h3><p>{city} · {country}</p></div><span class="arrow">↗</span></div></a>' for name,city,country,i in ps)
