def write(path,title,body,active=''):
 nav=''.join(f'<a class="{"active" if active==t else ""}" href="{u}">{t}</a>' for t,u in [('Work','/en/projects/'),('Expertise','/en/services/'),('Destinations','/en/destinations/'),('Studio','/en/about/')])
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Charlot Crea</title><meta name="description" content="Photography and film by Charlot Crea. Explore selected projects and discover our work."><link rel="stylesheet" href="/style.css"></head><body><header><a href="/" aria-label="Charlot Crea home"><img class="logo" src="/assets/logo.png" alt="Charlot creative"></a><nav id="nav">{nav}<a class="btn" href="/en/contact/">Discuss a project ↗</a></nav><button class="mobile-toggle" aria-label="Toggle navigation" aria-expanded="false" onclick="let n=document.getElementById('nav');n.classList.toggle('open');this.setAttribute('aria-expanded',n.classList.contains('open'))">☰</button></header><main>{body}</main><footer><span>© Charlot Crea · Photography & Film</span><span>Türkiye · Working internationally</span><span>Private concept preview · No enquiries are sent</span></footer><script src="/app.js"></script></body></html>'''
 p=D/path.strip('/')/'index.html' if path!='/' else D/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)
