hero2='''<section class="hero hero-filmstrip"><div class="hero-top"><div><span class="label">Photography · Film</span><h1>Four countries.<br/>One considered eye.</h1></div><p>A rotating look at selected hospitality photography from the Charlot Crea portfolio — click any photo for a closer look.<a href="/en/projects/">Discover our work ↗</a></p></div><div class="hero-filmstrip-viewport"><div class="hero-filmstrip-track">'''+filmstrip_items+'''</div></div><div class="below-image"><span>BASED IN TÜRKİYE. WORKING BEYOND BORDERS.</span><span>CLICK ANY PHOTO TO EXPLORE →</span></div></section><dialog class="gallery-dialog" aria-label="Photo viewer"><button class="gallery-close" aria-label="Close photo viewer">×</button><button class="gallery-prev" aria-label="Previous photograph">←</button><img alt=""><button class="gallery-next" aria-label="Next photograph">→</button><p class="gallery-count" aria-live="polite"></p></dialog><script>(()=>{const track=document.querySelector('.hero-filmstrip-track');if(!track)return;const originals=[...track.children];originals.forEach(el=>{const c=el.cloneNode(true);c.classList.remove('gallery-open');c.removeAttribute('href');c.setAttribute('aria-hidden','true');c.setAttribute('tabindex','-1');const im=c.querySelector('img');if(im)im.loading='lazy';track.append(c)});const loopPoint=track.children[originals.length].offsetLeft;const reduce=matchMedia('(prefers-reduced-motion: reduce)');let x=0,down=false,moved=false,startClientX=0,startX=0,hovering=false,visible=true;const section=track.closest('.hero');if(section)new IntersectionObserver(([e])=>{visible=e.isIntersecting},{threshold:0}).observe(section);function setX(v){x=v;track.style.transform='translateX('+x+'px)'}function paused(){return down||hovering||!visible||reduce.matches||document.querySelector('.gallery-dialog')?.open}track.addEventListener('mouseenter',()=>hovering=true);track.addEventListener('mouseleave',()=>hovering=false);track.addEventListener('focusin',()=>hovering=true);track.addEventListener('focusout',()=>hovering=false);track.addEventListener('pointerdown',e=>{down=true;moved=false;startClientX=e.clientX;startX=x;track.setPointerCapture(e.pointerId)});track.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-startClientX;if(Math.abs(dx)>4)moved=true;setX(Math.min(0,startX+dx))});function end(){down=false}track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false}},true);let last=null;function tick(ts){if(last===null)last=ts;const dt=Math.min(ts-last,50);last=ts;if(!paused()){setX(x-dt*0.05);if(x<=-loopPoint)setX(x+loopPoint)}requestAnimationFrame(tick)}requestAnimationFrame(tick)})();</script>'''
